local lastTime = tick()
local targetVolume = 0.5
local fadeInTime = 2
task.spawn(function()
    local steps = 20
    local stepTime = fadeInTime / steps
    for i = 1, steps do
        if sound then
            sound.Volume = targetVolume * (i / steps)
            task.wait(stepTime)
        end
    end
end)
playBtn.MouseButton1Click:Connect(function()
    currentFrame = 1
    sound.TimePosition = 0
    sound:Play()
end)
closeBtn.MouseButton1Click:Connect(function()
    screenGui:Destroy()
    sound:Stop()
    sound:Destroy()
end)
RunService.RenderStepped:Connect(function()
    local now = tick()
    if now - lastTime >= frameDelay / 1000 then
        lastTime = now
        for f = 1, totalFrames do
            for y = 1, 32 do
                for x = 1, 32 do
                    local p = pixelFrames[f] and pixelFrames[f][y] and pixelFrames[f][y][x]
                    if p then
                        p.Visible = (f == currentFrame)
                    end
                end
            end
        end
        currentFrame = currentFrame + 1
        if currentFrame > totalFrames then
            currentFrame = 1
        end
        if sound then
            sound.TimePosition = now - lastTime
        end
    end
end)